def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_12(n):
    if n == 1:
        return 1

    factors = prime_factorization(n)

    # tau(n^12) = product((12*a_i + 1)) for all a_i in the factorization of n
    tau = 1
    for exponent in factors.values():
        tau *= (12 * exponent + 1)
    return tau

